// Agent defines model for Agent.
type Agent struct {
	// Aca Which AI coding agent it runs, as claude_code.
	Aca string `json:"aca"`

	// Activity What it is doing, while running; otherwise null. Unknown when its screen cannot be read, or its process was started by a wdx too old to say.
	Activity *AgentActivity `json:"activity"`

	// Children The agents created under it, by name, with their children; set by listAgents, getAgent and getProject only.
	Children  *[]Agent  `json:"children,omitempty"`
	CreatedAt time.Time `json:"created_at"`

	// CurrentDir Where its AI CLI last said it worked, as after it moved into a worktree it made itself; null until it has, or when it does not say.
	CurrentDir *string `json:"current_dir"`

	// Dir Where it starts, now and on every relaunch.
	Dir string `json:"dir"`

	// Draft Whether a human left text in its input box, never the text, while running; otherwise null.
	Draft   *bool      `json:"draft"`
	EndedAt *time.Time `json:"ended_at"`

	// Error Only when failed; why it did not start.
	Error *string `json:"error"`

	// ExitCode Only when exited; 128 and the signal for one killed by a signal.
	ExitCode *int `json:"exit_code"`

	// Held Messages for it that wait for a human: their holder died, and what they were meant for is gone.
	Held int    `json:"held"`
	Id   string `json:"id"`

	// Model The AI model's name as its ACA last showed it, such as Haiku 5.5, for display, while running; otherwise null, as before it has shown one. A change it does not show, such as an automatic fallback, is not seen.
	Model *string `json:"model"`
	Name  string  `json:"name"`

	// ParentAgentId The agent it was created under; null at the top level.
	ParentAgentId *string `json:"parent_agent_id"`

	// ParentAgentName That agent's name; null at the top level.
	ParentAgentName *string `json:"parent_agent_name"`

	// Pid The AI coding agent's, while it has one.
	Pid         *int   `json:"pid"`
	ProjectId   string `json:"project_id"`
	ProjectName string `json:"project_name"`

	// Queued How many messages wait to go into it, as behind a draft, while running; otherwise null.
	Queued *int `json:"queued"`

	// RemovedAt When it was removed
	RemovedAt *time.Time `json:"removed_at"`

	// SessionId The AI coding agent's latest session, which it goes on with when started again; changes when the conversation is cleared.
	SessionId string     `json:"session_id"`
	StartedAt *time.Time `json:"started_at"`

	// State Whether its process is alive, not what its AI coding agent is doing.
	// starting: its holder is being started; running: its AI coding agent
	// is alive; exited: it ended by itself; stopped: closing its project
	// stopped it; failed: it did not start; lost: its holder is gone and
	// nobody stopped it; removed: it is a tombstone, kept until its children
	// are gone.
	State AgentState `json:"state"`

	// TerminalId What holds its process, which attaching dials; no terminal path accepts it.
	TerminalId string `json:"terminal_id"`

	// UpdatedAt When its state last changed.
	UpdatedAt time.Time `json:"updated_at"`

	// Worktree The name of the project's worktree holding dir, main for the clone; null when none does.
	Worktree *string `json:"worktree"`
}

